#!/usr/bin/env python
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
r"""任务 2：核对「正文引用了但 `sources:` 未登记」的候选 source 卡——判它是**证据**还是**只是参见**。

背景（2026-10-25 处置轮 2）
--------------------------
37 个 concept/topic 页的正文引用了 **137 张**库内 source 卡，但它们不在 `sources:` 里，
所以 `qc_evidence_base` 判它们「单源/二手」，而报告 §四 #3 已注明「判定可能偏低」。
要决定「补登记」还是「不补」，必须先分清候选卡在页内扮演什么角色：

  evidence  正文**论证段落**里引用了它（不在 `## 参见` / `## 参考` 区），且同一段落里有
            数字或定量/机理表述 ⇒ 它承载了该页的结论，**应补进 `sources:`**。
  seeref    只在 `## 参见` / `## 参考` 区出现 ⇒ 交叉引用/延伸阅读，**不应算作证据**。
  nameonly  正文出现但没有任何数字/限定语（纯提及）⇒ 证据强度弱，酌情。

判据全部来自页面文本本身，**不读候选卡内容**；本工具只做定位与分类，不下结论。
输出：控制台表 + `--json` 报告（含每个候选的命中行号与所在章节名，便于回查）。

用法
----
    python tools/qc_evidence_audit.py                    # 打印总表
    python tools/qc_evidence_audit.py --page 某概念页   # 单页明细
    python tools/qc_evidence_audit.py --json out.json
    python tools/qc_evidence_audit.py --selftest
"""
import os
import re
import sys
import json
import glob
import datetime

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, split_frontmatter, parse_frontmatter, console_encoding
import qc_evidence_base as QE

console_encoding()

SEE_HEADS = ("## 参见", "## 参考", "## 相关")
# 🔴 元数据区：本工具自己插入的「证据强度」注记就住在这里，注记里**列出了候选卡名**，
#    若不排除，该注记会被当成「论证区引用了该卡」→ 假 evidence（本轮实测踩过）。
META_HEADS = ("## 证据状态与判据",)
# 段落里只要有这些，就说明该处不是「顺口一提」而是带定量/机理的论证
QUANT_RE = re.compile(r"\d+(?:\.\d+)?\s*(?:%|mAh|Wh|mA|mS|S/cm|eV|Å|nm|μm|K|°C|℃|圈|次|倍|篇|h\b|s\b)")
CLAIM_RE = re.compile(r"作者|本文|该文|报道|提出|认为|发现|表明|证明|主张|归因|对照|实验|算得|实测")


def sections_of(body):
    """→ [(起始行号, 章节标题)]，用于判断某行属于哪一节。"""
    out = [(0, "(正文开头)")]
    for i, ln in enumerate(body.split("\n")):
        if ln.startswith("## "):
            out.append((i, ln.strip()))
    return out


def section_for(line_idx, secs):
    cur = secs[0][1]
    for i, h in secs:
        if line_idx >= i:
            cur = h
        else:
            break
    return cur


def is_see_section(head):
    return any(head.startswith(h) for h in SEE_HEADS)


def is_meta_section(head):
    return any(head.startswith(h) for h in META_HEADS)


def classify_candidate(body, card):
    """→ dict(role, hits=[(行号, 章节, 片段)])"""
    lines = body.split("\n")
    secs = sections_of(body)
    hits = []
    pat = re.compile(re.escape(card))
    for i, ln in enumerate(lines):
        if not pat.search(ln):
            continue
        head = section_for(i, secs)
        hits.append((i + 1, head, ln.strip()))
    if not hits:
        return {"role": "absent", "hits": []}
    # ① 元数据区（本工具插入的证据强度注记）不算任何角色，直接剔除
    hits = [h for h in hits if not is_meta_section(h[1])]
    if not hits:
        return {"role": "seeref", "hits": []}
    # ② 论证区（非参见区）命中：带定量/主张措辞 → evidence，否则 nameonly
    ev = [h for h in hits if not is_see_section(h[1])]
    for _i, _head, text in ev:
        if QUANT_RE.search(text) or CLAIM_RE.search(text):
            return {"role": "evidence", "hits": hits}
    if ev:
        return {"role": "nameonly", "hits": hits}
    # ③ 只在参见区：本库的惯例是「— 注解」式条目承载定量/机理细节 ⇒ 那是证据，不是延伸阅读；
    #    裸链接或短标签才算纯交叉引用。
    for _i, _head, text in hits:
        body_after = text.split("—", 1)[1] if "—" in text else ""
        # 本库惯例：「— 注解」式条目就是**承载内容**的引用（常含方法/结论细节）。
        # ⚠️ 不能用「有没有阿拉伯数字」判：标注里大量用下标数字（Ti₃C₂Tₓ）和化学式，
        #    QUANT_RE 抓不到 ⇒ 会把真证据误判成 seeref（本轮实测：MXene 条目被误判）。
        if len(body_after) >= 24:
            return {"role": "evidence", "hits": hits}
    return {"role": "seeref", "hits": hits}


def collect():
    src_pages = QE.load_source_pages()
    rows = []
    for d in ("wiki/concepts", "wiki/topics"):
        for f in sorted(glob.glob(os.path.join(d, "*.md"))):
            t = read_text(f)
            a, b = split_frontmatter(t)
            if not a:
                continue
            fm = parse_frontmatter(a)
            if fm.get("type") not in ("concept", "topic"):
                continue
            _fm, hits = QE.evidence_for(f, src_pages)
            val, why = QE.classify(hits)
            if val not in ("single-source", "secondhand"):
                continue
            srcs = fm.get("sources") or []
            if isinstance(srcs, str):
                srcs = [srcs]
            declared = {QE._resolve_source_name(s) for s in srcs}
            body_cards = set()
            for ln in re.findall(r"\[\[([^\[\]]+)\]\]", b):
                nm = ln.replace("\\|", "|").split("|")[0].split("#")[0].strip().replace("\\", "")
                nm = nm.split("/")[-1]
                if nm.endswith(".md"):
                    nm = nm[:-3]
                if nm in src_pages:
                    body_cards.add(nm)
            extra = sorted(body_cards - declared)
            if not extra:
                continue
            det = []
            for c in extra:
                cl = classify_candidate(b, c)
                det.append({"card": c, "role": cl["role"], "hits": cl["hits"][:4]})
            rows.append({"page": f.replace("\\", "/"), "value": val,
                         "n_declared": len(declared), "candidates": det})
    return rows


def main():
    args = sys.argv[1:]
    if "--help" in args or "-h" in args:
        print(__doc__)
        return 0
    if "--selftest" in args:
        return run_selftest()
    rows = collect()
    tot = sum(len(r["candidates"]) for r in rows)
    roles = {}
    for r in rows:
        for c in r["candidates"]:
            roles[c["role"]] = roles.get(c["role"], 0) + 1
    print("候选核对：%d 页 / %d 张候选卡" % (len(rows), tot))
    print("角色分布：", roles)
    print()
    only = None
    if "--page" in args:
        only = args[args.index("--page") + 1]
    for r in rows:
        if only and only not in r["page"]:
            continue
        ev = [c for c in r["candidates"] if c["role"] == "evidence"]
        nm = [c for c in r["candidates"] if c["role"] == "nameonly"]
        sr = [c for c in r["candidates"] if c["role"] == "seeref"]
        print("%-44s %-13s 候选 %2d = 证据 %2d / 提及 %d / 仅参见 %2d"
              % (r["page"].split("/")[-1][:-3], r["value"], len(r["candidates"]),
                 len(ev), len(nm), len(sr)))
        if only:
            for c in r["candidates"]:
                print("   [%-8s] %s" % (c["role"], c["card"]))
                for ln, head, text in c["hits"]:
                    print("        L%-4d %-18s %s" % (ln, head[:18], text[:90]))
    if "--json" in args:
        out = args[args.index("--json") + 1]
        with open(out, "w", encoding="utf-8") as fh:
            json.dump({"generated": datetime.date.today().isoformat(),
                       "rows": rows}, fh, ensure_ascii=False, indent=1)
        print("\n已写", out)
    return 0


def run_selftest():
    ok = True
    n = [0]

    def chk(name, cond, extra=""):
        nonlocal ok
        n[0] += 1
        print(("  PASS  " if cond else "  FAIL  ") + name + (("  " + extra) if extra else ""))
        if not cond:
            ok = False

    print("== qc_evidence_audit --selftest ==")
    body = ("# T\n\n正文提到 [[sources/卡A]] 报道 87 mAh g-1 的容量。\n\n"
            "## 参见\n\n- [[sources/卡B]] | [[sources/卡A]]\n")
    chk("论证区+定量 → evidence", classify_candidate(body, "卡A")["role"] == "evidence")
    chk("只在参见 → seeref", classify_candidate(body, "卡B")["role"] == "seeref")
    body2 = "# T\n\n正文里顺口提了 [[sources/卡C]]。\n\n## 参见\n"
    chk("论证区无数字无主张 → nameonly",
        classify_candidate(body2, "卡C")["role"] == "nameonly")
    chk("页面里没有 → absent", classify_candidate(body2, "卡Z")["role"] == "absent")
    body3 = "# T\n\n## 参考\n\n- [[sources/卡D]]\n"
    chk("## 参考 也算参见区", classify_candidate(body3, "卡D")["role"] == "seeref")
    print("\n%s (%d 项断言)" % ("全部 PASS" if ok else "有 FAIL", n[0]))
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
